:root{--bg:#0c1018;--surface:#151b28;--text:#eef2ff;--muted:#9aa6c2;--accent:#22c55e;--accent-2:#4ade80;--line:#273247;--max:1100px;--font:system-ui,sans-serif;--display:Georgia,serif}
*{box-sizing:border-box}body{margin:0;font-family:var(--font);color:var(--text);background:radial-gradient(ellipse at top,#182033 0%,var(--bg) 55%);line-height:1.55}
a{color:var(--accent-2);text-decoration:none}a:hover{color:var(--accent)}
.site-header{border-bottom:1px solid var(--line);background:rgba(12,16,24,.94);position:sticky;top:0;z-index:10}
.nav-inner{max-width:var(--max);margin:0 auto;padding:.85rem 1rem;display:flex;justify-content:space-between;gap:.75rem;align-items:center}
.brand{font-family:var(--display);font-size:1.2rem}.nav-links{display:flex;gap:.9rem;flex-wrap:wrap}.nav-links a{color:var(--muted)}
.nav-links a:hover,.nav-links a[aria-current=page]{color:var(--accent)}
.hero{max-width:var(--max);margin:0 auto;padding:3rem 1rem 2rem}.hero h1{font-family:var(--display);font-size:clamp(1.9rem,4.5vw,2.8rem);margin:0 0 .75rem;line-height:1.12}
.hero p{color:var(--muted);max-width:34rem}.btn{display:inline-block;margin-top:1rem;padding:.65rem 1rem;background:var(--accent);color:#0c1018;border-radius:4px;font-weight:600}
.site-footer{border-top:1px solid var(--line);margin-top:1.5rem;padding:1.4rem 1rem;color:var(--muted);text-align:center}
form{display:grid;gap:.7rem;max-width:28rem}label{display:grid;gap:.25rem;color:var(--muted);font-size:.9rem}
input,textarea,select{padding:.6rem .7rem;border-radius:6px;border:1px solid var(--line);background:var(--surface);color:var(--text);font:inherit}
button[type=submit]{justify-self:start;padding:.65rem 1rem;border:0;border-radius:4px;background:var(--accent);color:#0c1018;font-weight:600;cursor:pointer}
.section{max-width:var(--max);margin:0 auto;padding:1.5rem 1rem 2rem}.section h2{font-family:var(--display);font-size:1.5rem}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:1rem}
.card{background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:1rem}.card h3{margin-top:0;font-family:var(--display)}
.price{color:var(--accent-2);font-weight:700}.menu-list{list-style:none;padding:0;margin:0}
.menu-list li{display:flex;justify-content:space-between;gap:1rem;padding:.7rem 0;border-bottom:1px solid var(--line)}
@media (max-width:640px){.nav-inner{flex-direction:column;align-items:flex-start}}
